package com.dfsready;

/** Tracks server cooldown samples and estimates early warnings in game ticks. */
final class CooldownTracker
{
    private int previous = -1;
    private boolean tracking;
    private boolean warned;
    private int ticksSinceChange;

    boolean sample(int cooldown, boolean dfsEquipped)
    {
        return sample(cooldown, dfsEquipped, 0);
    }

    boolean sample(int cooldown, boolean dfsEquipped, int offsetSeconds)
    {
        int leadMillis = Math.max(0, Math.min(10, offsetSeconds)) * 1000;
        if (cooldown < 0)
        {
            suspend();
            return false;
        }
        if (previous < 0)
        {
            // Establish a baseline after login/hop/reconnect. Never alert on it.
            tracking = cooldown > 0 && (tracking || dfsEquipped);
            ticksSinceChange = 0;
            // Do not issue a catch-up warning when resuming inside the early window.
            warned = cooldown > 0 && (warned || cooldown * 4800 <= leadMillis);
            previous = cooldown;
            return false;
        }
        if (cooldown > previous)
        {
            // Shared draconic cooldown: only attribute a fresh cycle to an equipped DFS.
            tracking = dfsEquipped;
            warned = false;
        }
        ticksSinceChange = cooldown == previous ? Math.min(7, ticksSinceChange + 1) : 0;
        // The server value is quantized in eight-tick units. Never infer actual
        // readiness before it reaches zero, even if a sample is held unusually long.
        int remainingTicks = cooldown == 0 ? 0 : Math.max(1, cooldown * 8 - ticksSinceChange);
        boolean ready = tracking && !warned && previous > 0
            && (cooldown == 0 || (leadMillis > 0 && remainingTicks * 600 <= leadMillis));
        if (ready) { warned = true; }
        if (cooldown == 0)
        {
            tracking = false;
        }
        previous = cooldown;
        return ready;
    }

    void suspend()
    {
        previous = -1;
    }

    void reset()
    {
        previous = -1;
        tracking = false;
        warned = false;
        ticksSinceChange = 0;
    }
}

package com.dfsready;

import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.UnsupportedAudioFileException;
import net.runelite.client.audio.AudioPlayer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class DfsReadyChime
{
    private static final Logger LOG = LoggerFactory.getLogger(DfsReadyChime.class);
    private final AudioPlayer audioPlayer;
    private final ScheduledExecutorService executor;

    @Inject
    DfsReadyChime(AudioPlayer audioPlayer, ScheduledExecutorService executor)
    {
        this.audioPlayer = audioPlayer;
        this.executor = executor;
    }

    void play(int volume)
    {
        int clampedVolume = Math.max(0, Math.min(100, volume));
        if (clampedVolume == 0) { return; }
        float gain = (float) (20 * Math.log10(clampedVolume / 100.0));
        // Opening an audio device must not hold up the client/game thread.
        executor.execute(() ->
        {
            try
            {
                audioPlayer.play(DfsReadyChime.class, "/com/dfsready/soft-chime.wav", gain);
            }
            catch (IOException | UnsupportedAudioFileException | LineUnavailableException | RuntimeException ex)
            {
                // The visual alert remains available even with no usable audio device.
                LOG.debug("Unable to play DFS Ready chime", ex);
            }
        });
    }
}

package com.dfsready;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(DfsReadyConfig.GROUP)
public interface DfsReadyConfig extends Config
{
    String GROUP = "dfsready";

    @ConfigSection(name = "DFS Timer", description = "Cooldown warnings, screen flash and optional sound", position = 0)
    String TIMER_SECTION = "dfsTimer";

    @ConfigSection(name = "Attack Protection", description = "Optional equipment requirements for Attack menu entries", position = 1)
    String ATTACK_SECTION = "attackProtection";

    @ConfigItem(keyName = "flashColor", name = "Flash colour", description = "Colour of the cooldown-finished flash", position = 0, section = TIMER_SECTION)
    default Color flashColor() { return Color.RED; }

    @Range(min = 5, max = 60)
    @ConfigItem(keyName = "opacity", name = "Opacity (%)", description = "Maximum opacity of the translucent flash", position = 1, section = TIMER_SECTION)
    default int opacity() { return 25; }

    @Range(min = 200, max = 30000)
    @ConfigItem(keyName = "duration", name = "Duration (ms)", description = "Total flashing time in milliseconds: 2000 = 2 seconds, 5000 = 5 seconds. Maximum 30000 (30 seconds).", position = 2, section = TIMER_SECTION)
    default int duration() { return 2000; }

    @ConfigItem(keyName = "showText", name = "Show message", description = "Show cooldown finished or ending soon for early warnings; charges are not checked", position = 3, section = TIMER_SECTION)
    default boolean showText() { return false; }

    @ConfigItem(keyName = "equippedOnly", name = "Only alert while equipped", description = "Suppress the alert if the DFS is no longer equipped when the warning is due", position = 4, section = TIMER_SECTION)
    default boolean equippedOnly() { return false; }

    @ConfigItem(keyName = "hideAttackWithoutLoadout", name = "Enable PvE attack protection", description = "Hide NPC Attack unless all filled equipment fields match. Disabled in PvP areas/worlds; player entries are never changed. Does not stop existing combat.", position = 5, section = ATTACK_SECTION)
    default boolean hideAttackWithoutLoadout() { return false; }

    @ConfigItem(keyName = "playChime", name = "Play soft chime", description = "Play one gentle chime when the red flash starts. No Windows notification sound.", position = 6, section = TIMER_SECTION)
    default boolean playChime() { return false; }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "chimeVolume", name = "Chime volume (%)", description = "Volume of the soft alert chime; 0 mutes it", position = 7, section = TIMER_SECTION)
    default int chimeVolume() { return 35; }

    @ConfigItem(keyName = "attackWeapon", name = "Allowed weapon", description = "Exact item name or item ID. Blank ignores this slot; both slots blank disable the restriction.", position = 8, section = ATTACK_SECTION)
    default String attackWeapon() { return "Bronze crossbow"; }

    @ConfigItem(keyName = "attackShield", name = "Allowed shield", description = "Exact item name or item ID. Blank ignores this slot; both slots blank disable the restriction.", position = 9, section = ATTACK_SECTION)
    default String attackShield() { return "Dragonfire shield"; }

    @Range(min = 0, max = 10)
    @ConfigItem(keyName = "warningOffset", name = "Warn early (seconds)", description = "Warn approximately 0-10 seconds before cooldown ends. 0 waits for confirmed readiness. One alert per cooldown.", position = 10, section = TIMER_SECTION)
    default int warningOffset() { return 0; }

    @ConfigItem(keyName = "desktopNotification", name = "Windows / desktop notification", description = "Show one desktop notification when the cooldown alert fires. Off by default. Delivery depends on system notification settings.", position = 11, section = TIMER_SECTION)
    default boolean desktopNotification() { return false; }
}

package com.dfsready;

import java.awt.Color;
import java.awt.Canvas;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class DfsReadyOverlay extends Overlay
{
    private final Client client;
    private final DfsReadyConfig config;
    private final LongSupplier clock;
    private volatile long start;
    private volatile long duration;
    private volatile String message = "DFS cooldown finished";

    @Inject
    DfsReadyOverlay(Client client, DfsReadyConfig config)
    {
        this(client, config, System::nanoTime);
    }

    DfsReadyOverlay(Client client, DfsReadyConfig config, LongSupplier clock)
    {
        this.client = client;
        this.config = config;
        this.clock = clock;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
    }

    void flash()
    {
        message = "DFS cooldown finished";
        startFlash();
    }

    void flashEarly()
    {
        message = "DFS cooldown ending soon";
        startFlash();
    }

    private void startFlash()
    {
        start = clock.getAsLong();
        duration = Math.max(200, Math.min(30000, config.duration())) * 1_000_000L;
    }

    void clear() { duration = 0; }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        long length = duration;
        long elapsed = clock.getAsLong() - start;
        if (length == 0 || elapsed < 0 || elapsed >= length || client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }
        // Match RuneLite's notification cadence without invoking Notifier, which can
        // also send desktop notifications, play sounds, or request window focus.
        if ((elapsed / 400_000_000L) % 2 != 0) { return null; }
        Canvas canvas = client.getCanvas();
        if (canvas == null) { return null; }
        int x = 0;
        int y = 0;
        int width = canvas.getWidth();
        int height = canvas.getHeight();
        if (width <= 0 || height <= 0) { return null; }

        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.clipRect(x, y, width, height);
            int alpha = (int) Math.round(255 * Math.max(5, Math.min(60, config.opacity())) / 100.0);
            Color color = config.flashColor();
            g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha));
            g.fillRect(x, y, width, height);
            if (config.showText())
            {
                FontMetrics metrics = g.getFontMetrics();
                int textX = x + (width - metrics.stringWidth(message)) / 2;
                int textY = y + height / 3;
                g.setColor(new Color(0, 0, 0, 200));
                g.fillRoundRect(textX - 12, textY - metrics.getAscent() - 8,
                    metrics.stringWidth(message) + 24, metrics.getHeight() + 16, 12, 12);
                g.setColor(Color.WHITE);
                g.drawString(message, textX, textY);
            }
        }
        finally { g.dispose(); }
        return null;
    }
}

package com.dfsready;

import com.google.inject.Provides;
import java.awt.TrayIcon;
import java.util.Arrays;
import java.util.EnumSet;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.Notifier;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(name = "DFS Timer and Attack Protection", description = "Dragonfire shield cooldown alerts and optional equipment-based Attack menu protection", tags = {"dragonfire", "shield", "cooldown", "flash"})
public class DfsReadyPlugin extends Plugin
{
    private static final Notification DESKTOP_ALERT = new Notification()
        .withEnabled(true).withInitialized(true).withOverride(true)
        .withTray(true).withTrayIconType(TrayIcon.MessageType.INFO)
        .withRequestFocus(RequestFocusType.OFF).withSound(NotificationSound.OFF)
        .withFlash(FlashNotification.DISABLED).withGameMessage(false)
        .withSendWhenFocused(true).withTimeout(5000);

    @Inject private Client client;
    @Inject private DfsReadyConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private DfsReadyOverlay overlay;
    @Inject private DfsReadyChime chime;
    @Inject private Notifier notifier;
    private final CooldownTracker tracker = new CooldownTracker();

    @Provides
    DfsReadyConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(DfsReadyConfig.class);
    }

    @Override
    protected void startUp()
    {
        tracker.reset();
        overlay.clear();
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        overlay.clear();
        tracker.reset();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();
        if (state == GameState.LOGGED_IN) { return; }
        overlay.clear();
        if (state == GameState.LOGIN_SCREEN || state == GameState.LOGIN_SCREEN_AUTHENTICATOR
            || state == GameState.LOGGING_IN || state == GameState.STARTING)
        {
            tracker.reset();
        }
        else
        {
            tracker.suspend();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN) { return; }
        boolean equipped = dfsEquipped();
        int cooldown = client.getVarbitValue(VarbitID.DRAGONFIRE_SHIELD_RECHARGE);
        boolean ready = tracker.sample(cooldown, equipped, config.warningOffset());
        if (ready && (!config.equippedOnly() || equipped))
        {
            if (cooldown > 0) { overlay.flashEarly(); }
            else { overlay.flash(); }
            if (config.playChime())
            {
                chime.play(config.chimeVolume());
            }
            if (config.desktopNotification())
            {
                notifier.notify(DESKTOP_ALERT, cooldown > 0
                    ? "DFS cooldown ending soon."
                    : "DFS cooldown finished.");
            }
        }
    }

    private boolean dfsEquipped()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        Item shield = equipment == null ? null : equipment.getItem(EquipmentInventorySlot.SHIELD.getSlotIdx());
        return shield != null && shield.getId() == ItemID.DRAGONFIRE_SHIELD;
    }

    @Subscribe
    public void onPostMenuSort(PostMenuSort event)
    {
        if (!config.hideAttackWithoutLoadout() || client.getGameState() != GameState.LOGGED_IN
            || client.isMenuOpen() || isPvpContext() || attackLoadoutEquipped())
        {
            return;
        }
        MenuEntry[] entries = client.getMenuEntries();
        MenuEntry[] filtered = Arrays.stream(entries)
            .filter(entry -> !isAttackEntry(entry))
            .toArray(MenuEntry[]::new);
        if (filtered.length != entries.length)
        {
            client.setMenuEntries(filtered);
        }
    }

    private boolean attackLoadoutEquipped()
    {
        String requiredWeapon = config.attackWeapon().trim();
        String requiredShield = config.attackShield().trim();
        if (requiredWeapon.isEmpty() && requiredShield.isEmpty()) { return true; }
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        if (equipment == null) { return false; }
        Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
        Item shield = equipment.getItem(EquipmentInventorySlot.SHIELD.getSlotIdx());
        return (requiredWeapon.isEmpty() || matchesItem(weapon, requiredWeapon))
            && (requiredShield.isEmpty() || matchesItem(shield, requiredShield));
    }

    private boolean isPvpContext()
    {
        EnumSet<WorldType> worldTypes = client.getWorldType();
        return worldTypes == null || WorldType.isPvpWorld(worldTypes)
            || worldTypes.contains(WorldType.DEADMAN)
            || worldTypes.contains(WorldType.PVP_ARENA)
            || client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) != 0
            || client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) != 0
            || client.getVarbitValue(VarbitID.PVP_ADJACENT_AREA_CLIENT) != 0;
    }

    private boolean matchesItem(Item item, String required)
    {
        if (item == null) { return false; }
        String value = required.trim();
        if (value.matches("[0-9]+"))
        {
            return Integer.toString(item.getId()).equals(value);
        }
        ItemComposition definition = client.getItemDefinition(item.getId());
        return definition != null && value.equalsIgnoreCase(Text.removeTags(definition.getName()));
    }

    private static boolean isAttackEntry(MenuEntry entry)
    {
        if (!"Attack".equalsIgnoreCase(Text.removeTags(entry.getOption()))) { return false; }
        MenuAction type = entry.getType();
        return type == MenuAction.NPC_FIRST_OPTION || type == MenuAction.NPC_SECOND_OPTION
            || type == MenuAction.NPC_THIRD_OPTION || type == MenuAction.NPC_FOURTH_OPTION
            || type == MenuAction.NPC_FIFTH_OPTION;
    }
}

package com.dfsready;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public final class DfsReadyLauncher
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(DfsReadyPlugin.class);
        RuneLite.main(args);
    }
}
